    lons = [10.0, 11.0] if lons is None else lons
    return {"schema": "climate-grid/idw-v1", "lats": lats, "lons": lons,
            "values": [[1.0 for _ in lons] for _ in lats],
            "counts": [[1 for _ in lons] for _ in lats]}


def good_ds(elements=("a",), grids=None):
    grids = grids or {e: good_grid() for e in elements}
    return {"schema": "climate-grid/dataset-v1", "data": dict(grids)}


def good_frame(day="2024-01-01", ds=None):
    return {"time": day, "dataset": ds or good_ds()}


def classify(fn, frames, **kw):
    try:
        fn(copy.deepcopy(frames), **kw)
        return None
    except TypeError:
        return "T"
    except ValueError:
        return "V"
    except Exception as e:
        return type(e).__name__


rng = random.Random(7)
mutations = []

def mutate(x, depth=0):
    """Generate one mutated deep copy of a valid frame structure."""
    y = copy.deepcopy(x)
    kind = rng.randrange(12)
    if isinstance(y, list):
        if kind == 0 and y:
            y[rng.randrange(len(y))] = None
        elif kind == 1:
            y = "notalist"
        elif kind == 2:
            y = tuple(y)
        elif y:
            y.append(copy.deepcopy(y[0]))
        return y
    if isinstance(y, dict):
        if kind == 0:
            return ["not", "a", "dict"]
        if kind == 1 and y:
            k = rng.choice(list(y.keys()))
            y[k] = None
        elif kind == 2 and y:
            k = rng.choice(list(y.keys()))
            y[k + "_extra"] = 1
        elif kind == 3 and y:
            k = rng.choice(list(y.keys()))
            del y[k]
        elif kind == 4:
            y = {}
        return y
    return y


def random_bad():
    frames = [good_frame("2024-01-01"), good_frame("2024-01-03", good_ds())]
    choice = rng.randrange(14)
    if choice == 0:
        frames = []
    elif choice == 1:
        frames = "x"
    elif choice == 2:
        frames = [None]
    elif choice == 3:
        frames = [("2024-01-01", good_ds())]
    elif choice == 4:
        f = good_frame(); del f["time"]; frames = [f]
    elif choice == 5:
        frames = [good_frame(20240101)]
    elif choice == 6:
        frames = [good_frame("2024-01-01"), good_frame("2024-01-01")]
    elif choice == 7:
        f = good_frame(); f["time"] = "2024/01/01"; frames = [f]
    elif choice == 8:
        f = good_frame(); f["dataset"] = good_ds(); f["dataset"]["schema"] = "x"
        frames = [f]
    elif choice == 9:
        f = good_frame(); g = good_grid(); g["values"][0][0] = "x"
        f["dataset"] = {"schema": "climate-grid/dataset-v1", "data": {"a": g}}
        frames = [f]
    elif choice == 10:
        g = good_grid(); g["lats"] = [1.0, 0.0]
        frames = [good_frame(ds={"schema": "climate-grid/dataset-v1",
