    elif choice == 11:
        frames = [good_frame(), good_frame(
            "2024-01-02",
            {"schema": "climate-grid/dataset-v1",
             "data": {"a": good_grid(lats=[0.0, 2.0])}})]
    elif choice == 12:
        g = good_grid(); g["counts"][0][0] = -3
        frames = [{"time": "2024-01-01",
                   "dataset": {"schema": "climate-grid/dataset-v1",
                               "data": {"a": g}}}]
    elif choice == 13:
        frames = [good_frame(), good_frame(
