            {"schema": "climate-grid/dataset-v1",
             "data": {"b": good_grid()}})]
    return frames


gap_values = [2, 0, -1, True, False, 1.0, "2", None]
for trial in range(600):
    frames = random_bad()
    gap = rng.choice(gap_values)
    rm = classify(mine.reconstruct, frames, max_gap=gap)
    rr = classify(ref.reconstruct, frames, max_gap=gap)
    assert rm == rr, f"trial {trial}: mine={rm} ref={rr}, gap={gap}, frames={frames}"

# Also structural fuzz: mutate arbitrary nested pieces
base = [good_frame("2024-01-01"), good_frame("2024-01-04", good_ds())]
for trial in range(400):
    bad = copy.deepcopy(base)
    path_picks = rng.randrange(5)
    target = bad[rng.randrange(len(bad))]
    for _ in range(path_picks):
        if isinstance(target, dict) and target:
            target = target[rng.choice(list(target.keys()))]
        elif isinstance(target, list) and target:
            target = target[rng.randrange(len(target))]
        else:
            break
    # can't reassign into parent from here; instead wrap whole frame mutations:
    f = bad[rng.randrange(len(bad))]
    slot = rng.choice(["time"])
    f[slot] = rng.choice([None, 5, "2024-1-1", "2024-02-30", "9999-99-99"])
    rm = classify(mine.reconstruct, bad)
    rr = classify(ref.reconstruct, bad)
    assert rm == rr, f"fuzz trial {trial}: mine={rm} ref={rr}"

print("ERROR-PARITY TESTS PASSED")

